package com.hms.website;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="hospital_website_settings") public class WebsiteSettings { @Id private UUID id; @Column(nullable=false,unique=true) private UUID tenantId; @Column(length=500) private String logoUrl; @Column(length=20) private String primaryColor; @Column(length=20) private String secondaryColor; @Column(length=100) private String fontFamily; @Column(length=300) private String tagline; @Column(length=40) private String contactPhone; @Column(length=180) private String contactEmail; @Column(length=500) private String address; @Column(length=500) private String facebookUrl; @Column(length=500) private String instagramUrl; @Column(length=500) private String youtubeUrl; @Column(nullable=false) private boolean published; @Column(nullable=false) private OffsetDateTime updatedAt; protected WebsiteSettings(){} public WebsiteSettings(UUID tenantId,UpdateWebsiteSettingsRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;apply(r);this.updatedAt=OffsetDateTime.now();} public void apply(UpdateWebsiteSettingsRequest r){logoUrl=r.logoUrl();primaryColor=r.primaryColor();secondaryColor=r.secondaryColor();fontFamily=r.fontFamily();tagline=r.tagline();contactPhone=r.contactPhone();contactEmail=r.contactEmail();address=r.address();facebookUrl=r.facebookUrl();instagramUrl=r.instagramUrl();youtubeUrl=r.youtubeUrl();published=r.published();updatedAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getLogoUrl(){return logoUrl;} public String getPrimaryColor(){return primaryColor;} public String getSecondaryColor(){return secondaryColor;} public String getFontFamily(){return fontFamily;} public String getTagline(){return tagline;} public String getContactPhone(){return contactPhone;} public String getContactEmail(){return contactEmail;} public String getAddress(){return address;} public String getFacebookUrl(){return facebookUrl;} public String getInstagramUrl(){return instagramUrl;} public String getYoutubeUrl(){return youtubeUrl;} public boolean isPublished(){return published;} }
